0.7023000]';
Sample=[cqsrfls15];

%calculate XYZWT and XYZT
[XYZT_,XYZWT_]=spd2xyz(S1,2,0,Sample);

CCT=CCTa(XYZWT_);T=CCT;

%calculate reference illuminant
Sr=CCT2CIEref(CCT,lambda);


%calculate XYZR and XYZWR
[XYZR_,XYZWR_]=spd2xyz(Sr,2,0,Sample);

N=size(S1,2)-1;
for j=1:N;
    XYZT=XYZT_(:,:,j);
    XYZWT=XYZWT_(j,:);
    XYZR=XYZR_(:,:,j);
    XYZWR=XYZWR_(j,:);

    %calc corresponding colours of munsell under D65
    XYZTc=xyz2xyzc(XYZT,XYZWT,XYZWR,1000,1000);
    XYZWTc=xyz2xyzc(XYZWT,XYZWT,XYZWR,1000,1000);

    LABt=xyz2lab(XYZTc,XYZWTc);
    LAB_Ct=sqrt(LABt(:,2).^2+LABt(:,3).^2);%LAB_ht=atan(LABt(:,3)./LABt(:,2));
    LABr=xyz2lab(XYZR,XYZWR);
    LAB_Cr=sqrt(LABr(:,2).^2+LABr(:,3).^2);%LAB_hr=atan(LABr(:,3)./LABr(:,2));


    deltaLstar=(LABt(:,1)-LABr(:,1));
    deltaastar=(LABt(:,2)-LABr(:,2));
    deltabstar=(LABt(:,3)-LABr(:,3));
    deltaE=sqrt(deltaLstar.^2+deltaastar.^2+deltabstar.^2);%calculate individual deltaE's

    deltaC=LAB_Ct-LAB_Cr;
    deltaEf=deltaE;%save for Qf;
    deltaCo=deltaC;
    deltaE(deltaC>0)=sqrt(deltaE(deltaC>0).^2-deltaC(deltaC>0).^2);%increase in chroma is not penalized!


    deltaERMS=sqrt(sum(deltaE.^2)./numel(deltaE)); %take RMS average for Qa
    deltaERMSf=sqrt(sum(deltaEf.^2)./numel(deltaEf));%take RMS average for Qf

    %calculate relative Gamut area Qg
    Qg(j)=100.*polyarea(LABt(:,2),LABt(:,3))./polyarea(LABr(:,2),LABr(:,3));


    %calculate Gamut area correction
    % %calc corresponding colours of munsell under D65
    % XYZwD65=[9.5042e+001  1.0000e+002  1.0888e+002];%D65 ref for GA factor
    % XYZRc=xyz2xyzc(XYZR,XYZWR,XYZwD65,1000,1000);%ref under D65, to use in GAI calc.
    % XYZWRc=xyz2xyzc(XYZWR,XYZWR,XYZwD65,1000,1000);
    % LABD65=xyz2lab(XYZRc,XYZWRc);%ref under D65, to use in GAI calc.
    % GAD65=8210;
    % GA=polyarea(LABD65(:,2),LABD65(:,3));
    % GA=GA/GAD65;GA(GA>1)=1;
    GA(j) = T(j).^3.*(9.2672.*10.^(-11))-T(j).^2.*(8.3959.*10.^(-7))+T(j).*0.00255-1.612;%alternative to rigorous GA calculation
    if GA(j)>1;GA(j)=1;end
    
    Qai(:,j)=(100-deltaE.*cfactor_a);
    Qai(:,j)=GA(j).*log(exp(Qai(:,j)./10)+1).*10;
%     if size(Qai(:,1))==1;Qai=Qai';end
    DERMS=deltaERMS;
    Qa(j)=(100-deltaERMS.*cfactor_a);
    Qa(j)=GA(j).*log(exp(Qa(j)/10)+1).*10;
    dERMSa=deltaERMS;

    %colour fidelity
    Qf(j)=(100-deltaERMSf.*cfactor_f);
    Qf(j)=GA(j).*log(exp(Qf(j)/10)+1).*10;
    dERMSf=deltaERMSf;

    %colour preference
    deltaCmu=mean(deltaC.*(deltaC>=0));
    Qp(j)=100-cfactor_p.*(deltaERMS-deltaCmu);
    Qp(j)=GA(j).*log(exp(Qp(j)/10)+1).*10;
    dERMSp=deltaERMS-deltaCmu;

    DErms(j,:)=[dERMSa,dERMSf,dERMSp];
end

end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function XYZc=xyz2xyzc(XYZ,XYZtw,XYZrw,Lt,Lr);
%CMCCAT
MCAT=[0.7982,	0.3389,	-0.1371;
        -0.5918,	1.5512,	0.0406;
        0.0008,	0.0239,	0.9753];

MCATi=inv(MCAT);

%degree of adaptation
D=0.08*log10(Lt+Lr)+0.76-0.45*(Lt-Lr)/(Lt+Lr);
if D>1;D=1;end

Y=XYZ(2);

XYZ=XYZ./XYZ(2);
XYZtw=XYZtw./XYZtw(2);
XYZrw=XYZrw./XYZrw(2);


% Convert XYZ data to CAT02 LMS space
RGB=(MCAT*XYZ')';
R=RGB(:,1);G=RGB(:,2);B=RGB(:,3);

RGBtw=(MCAT*XYZtw')';
RGBrw=(MCAT*XYZrw')';
Rtw=RGBtw(:,1);Gtw=RGBtw(:,2);Btw=RGBtw(:,3);
Rrw=RGBrw(:,1);Grw=RGBrw(:,2);Brw=RGBrw(:,3);

% Apply chromatic adaptation (
Rc=(D.*(Rrw./Rtw)+1-D).*R;
Gc=(D.*(Grw./Gtw)+1-D).*G;
Bc=(D.*(Brw./Btw)+1-D).*B;

RGBc=[Rc,Gc,Bc];

% Calculate XYZ
XYZc=(MCATi*[Rc,Gc,Bc]')';
XYZc=XYZc.*Y;

end
